import{_ as a,c as t,o as r,ae as i}from"./chunks/framework.DI6M9D4h.js";const s="/assets/resistor-i2c-5v-1.BbSYh-DR.jpg",o="/assets/remove-resistors-1.DNVdA_xT.jpg",p="/assets/remove-resistors-2.B0954oZH.jpg",l="/assets/header-solder-1.BAvP7xd9.jpg",n="/assets/header-preparation-1.C6mdccrr.jpg",d="/assets/header-preparation-2.CHpRjNzZ.jpg",h="/assets/placed-adapter-pcb-1.D_cQWtLB.jpg",c="/assets/ffc-cable-orientation-1.Bk1fCMJQ.jpg",k="/assets/ffc-cable-orientation-2.CWlsAbhp.jpg",P=JSON.parse('{"title":"GlidePoint Cirque Trackpad with Adapter PCB","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/cirque-trackpad/index.md","filePath":"build-guides/cirque-trackpad/index.md","lastUpdated":1754311133000}'),m={name:"build-guides/cirque-trackpad/index.md"};function u(b,e,g,f,_,C){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="glidepoint-cirque-trackpad-with-adapter-pcb" tabindex="-1">GlidePoint Cirque Trackpad with Adapter PCB <a class="header-anchor" href="#glidepoint-cirque-trackpad-with-adapter-pcb" aria-label="Permalink to &quot;GlidePoint Cirque Trackpad with Adapter PCB&quot;">​</a></h1><h2 id="adapter-pcb" tabindex="-1">Adapter PCB <a class="header-anchor" href="#adapter-pcb" aria-label="Permalink to &quot;Adapter PCB&quot;">​</a></h2><p>The Adapter PCB can be used on any keyboard with a I2C oled display connector like the CRKBD, Lily58, or Kimiko.</p><p>The Adapter PCB has two 4.7k pull up resistor for I2C, to make it split keyboard compatible with serial communication.</p><h2 id="spi-or-i2c" tabindex="-1">SPI or I2C <a class="header-anchor" href="#spi-or-i2c" aria-label="Permalink to &quot;SPI or I2C&quot;">​</a></h2><p>The Cirque trackpad if configured by default for SPI. To use it with the I2C Adapter PCB, you have to remove a resistor (<strong>R1</strong>).</p><h2 id="_3v-or-5v" tabindex="-1">3V or 5V <a class="header-anchor" href="#_3v-or-5v" aria-label="Permalink to &quot;3V or 5V&quot;">​</a></h2><p>You can power the Cirque trackpad by default with 2.5-3.6V and use it for example with a SparkFun Pro Micro RP2040. To use a 5V controller, you have to remove two resistors (<strong>R7, R8</strong>).</p><p><img src="'+s+'" alt="Configuration resistor for I2C and 5V" loading="lazy"></p><h2 id="how-to-remove-the-resistors" tabindex="-1">How to remove the resistors <a class="header-anchor" href="#how-to-remove-the-resistors" aria-label="Permalink to &quot;How to remove the resistors&quot;">​</a></h2><p>You can use a hot air gun to remove the resistors. Be careful to not melt the FFC connector.</p><p>To use a solder iron to remove the resistor, put some solder on the tip. Touch the resistor sideways with the solder iron tip and push it carefully aside.</p><p><img src="'+o+'" alt="Remove resistor with a solder iron" loading="lazy"></p><p>Clean the solder points with some desoldering wire, to remove the remaining solder.</p><p><img src="'+p+'" alt="Clean solder points" loading="lazy"></p><h2 id="assembly" tabindex="-1">Assembly <a class="header-anchor" href="#assembly" aria-label="Permalink to &quot;Assembly&quot;">​</a></h2><p>Solder the 4pin header to the Adapter PCB.</p><p><img src="'+l+'" alt="Soldered 4pin header" loading="lazy"></p><p>If you use low profile sockets for you controller like the Mill-Max Series 315, remove the black plastic and shorten the legs with your pliers. This way you can mount the Adapter PCB low as possible.</p><p>Lift the plastic carefully with the pliers.</p><p><img src="'+n+'" alt="Remove plastic spacer" loading="lazy"></p><p>Shorten the pins with the pliers.</p><p><img src="'+d+'" alt="Lowered header" loading="lazy"></p><p>Place the Adapter PCB on the oled socket (I2C).</p><p><img src="'+h+'" alt="Placed Adapter board on oled socket" loading="lazy"></p><p>Lift the black part of the FFC cable connector and insert the cable with blue part facing up.</p><blockquote><p>The FFC/FPC cable is a 12 position with 0.5mm pitch.</p></blockquote><p><img src="'+c+'" alt="FFC cable orientation" loading="lazy"></p><p>Then insert the cable into the trackpad. The blue part on the cable must be facing to the black dot on the cable connector.</p><p><img src="'+k+`" alt="FFC cable orientation" loading="lazy"></p><h2 id="qmk-firmware-support" tabindex="-1">QMK firmware support <a class="header-anchor" href="#qmk-firmware-support" aria-label="Permalink to &quot;QMK firmware support&quot;">​</a></h2><p>Add the following lines to your <code>rules.mk</code>. For example <code>qmk_firmware/keyboards/crkbd/keymaps/default/rules.mk</code></p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POINTING_DEVICE_ENABLE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> yes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POINTING_DEVICE_DRIVER </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cirque_pinnacle_i2c</span></span></code></pre></div><p>To rotate or invert the trackpad this to your <code>config.h</code>:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> POINTING_DEVICE_ROTATION_90</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> POINTING_DEVICE_INVERT_X</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> POINTING_DEVICE_INVERT_Y</span></span></code></pre></div><p>Check the <a href="https://docs.qmk.fm/#/feature_pointing_device?id=cirque-trackpad" target="_blank" rel="noreferrer">QMK docs</a> for more settings.</p><p>Compile the firmware <code>qmk compile -kb crkbd -km default</code> and flash the hex file with <a href="https://github.com/qmk/qmk_toolbox" target="_blank" rel="noreferrer">QMK Toolbox</a>.</p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>The Adapter PCB is made by <a href="https://twitter.com/bom_tarnes" target="_blank" rel="noreferrer">@bom_tarnes</a> and is <a href="https://github.com/keyboard-magpie/minimal-fpc-i2c-pcb" target="_blank" rel="noreferrer">open source</a>.</p><p>Inspired by beekeeb and his <a href="https://beekeeb.com/cirque-trackpad-i2c-on-corne-keyboard/" target="_blank" rel="noreferrer">build guide</a>.</p>`,40)])])}const w=a(m,[["render",u]]);export{P as __pageData,w as default};
